  pageViewId?: string;
  // Unique identifier for the current user session. If omitted, generated and echoed back for use in future requests.
  sessionId?: string;
  // The user agent of the AI service making the request, e.g. 'mcp-server/1.0.0'. This is a value that represents you (the AI), but should be consistent across requests from the same AI service.
  userAgent?: string;
