  // The number of rooms required for the hotel stays. This defaults to 1 room.
  rooms?: number;
  // A copy of the fields normally set in the `_meta` section of the request. If you are calling from an LLM, this can be left out.
  toolRequestMetadata?: {
  // The BCP 47 locale of the user making the request, e.g. 'en-GB'.
  locale?: string;
  // The subject identifier of the user making the request.
  subject?: string;
  // The user-agent string of the client making the request.
  userAgent?: string;
